 bool Insert(const std::string& name,const TypedRow& values,const std::atomic_bool* cancellation)override{Writable();Session session(profile_,cancellation);Existing(session,name);auto result=Execute({{"collection",name},{"operation","insert_one"},{"document",RowJson(values)}},"",1,cancellation);if(!result.error.empty())throw std::runtime_error(result.error);return result.rowsAffected==1;}
