private:
 void Writable()const{if(profile_.readOnly)throw std::runtime_error("This connection is read-only.");}
 static void Key(const TypedRow& key){if(key.size()!=1||!key.count("_id")||key.at("_id").type==DbValueType::Null)throw std::runtime_error("Provide the _id primary key to identify one document.");}
